            first=iw16(a+0x54);second=iw16(a+IA_Y);if(a[IA_VY]&128u) {index=first;first=second;second=index;}
            if(second>=first) {
                a[IA_STEP]+=2;ip16(a+IA_Y,iw16(a+0x54));*ig(w,IG_FLAGS+type-4)=a[IA_KIND];ip32(a+IA_SEQUENCE,iw32(a+IA_SEQUENCE)+16);
            }
